package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
import io.knowledgebrain.contracts.collaboration.submissiongrade.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class SubmissionGradeStoreIntegrationTest {
 SubmissionStoreIntegrationTest f;SubmissionGradeStore store;SubmissionStore.Submission answer;
 @BeforeEach void setup(){f=new SubmissionStoreIntegrationTest();f.setup();f.open();answer=f.submit(f.f.key(),0,2,"Original answer").submission();store=new SubmissionGradeStore(f.f.source,f.parent.store,f.store,Clock.systemUTC());}
 SubmissionGradeStore.Grade change(long version,long reviewed,String reason){return store.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,version,new SubmissionGradeInput(80,reason,reviewed,2),f.f.trace);}
 SubmissionGradeStore.View get(UUID actor,boolean owner){return store.get(f.group,f.space,f.study,f.assignment,answer.submissionId(),actor,owner);}
 SubmissionGradeStore.History history(long before,int limit){return store.history(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false,before,limit);}
 void status(int code,org.junit.jupiter.api.function.Executable action){f.status(code,action);}
 @Test void absentGradeHasNoPersistentIdAuditOrEvent(){assertNull(get(f.author,false).grade());assertFalse(get(f.author,false).canWrite());assertTrue(get(f.f.owner,true).canWrite());assertEquals(1,get(f.author,false).submissionVersion());assertTrue(history(Long.MAX_VALUE,5).items().isEmpty());assertEquals(0,f.f.jdbc.queryForObject("SELECT count(*) FROM submission_grade WHERE submission_id=?",Integer.class,answer.submissionId()));}
 @Test void fullGradeAuditAndProtobufPinTheImmutableAnswer()throws Exception{
  var v=change(0,1,"Grade <script>\n의견");assertEquals(7,v.gradeId().version());assertEquals(f.author,v.authorId());assertEquals(f.f.owner,v.graderId());assertEquals(1,v.submissionVersion());assertEquals(2,v.assignmentVersion());assertEquals("AUTHOR_AND_OWNER",v.audience());assertEquals(v,get(f.author,false).grade());assertEquals(v,history(Long.MAX_VALUE,5).items().getFirst().snapshot());
  var e=SubmissionGradeEnvelopeV1.parseFrom(f.f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.gradeId()));var p=SubmissionGradeSnapshotV1.parseFrom(e.getPayload());assertEquals(f.f.trace,e.getTraceId());assertEquals(f.space.toString(),e.getSpaceId());assertEquals(f.f.owner.toString(),e.getActorId());assertEquals("SubmissionGrade",e.getAggregateType());assertEquals(80,v.score());assertEquals(v.score(),p.getScore());assertEquals("SubmissionGradeRecorded",e.getEventType());assertEquals(v.reason(),p.getReason());assertEquals(answer.submissionId().toString(),p.getSubmissionId());assertEquals(1,p.getSubmissionVersion());assertEquals("AUTHOR_AND_OWNER",p.getAudience());assertEquals(answer,f.store.get(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false));assertEquals(1,f.events(answer.submissionId()));
 }
 @Test void gradeHasIndependentVersionAndStableNoOp(){var first=change(0,1,"First");assertEquals(first,change(1,1,"First"));status(412,()->change(0,1,"First"));var corrected=change(1,1,"Corrected");assertEquals(first.gradeId(),corrected.gradeId());assertEquals(first.createdAt(),corrected.createdAt());assertEquals(2,corrected.version());assertEquals(1,get(f.author,false).submissionVersion());assertEquals(2,f.events(first.gradeId()));}
 @Test void newAnswerDoesNotAutomaticallyChangeGradeAndOldReviewCannotSave(){var first=change(0,1,"Check this part");var second=f.submit(f.f.key(),1,2,"Revised answer").submission();assertEquals(first,get(f.author,false).grade());assertEquals(2,get(f.author,false).submissionVersion());status(409,()->change(1,1,"Old review"));var next=change(1,2,"Check this part");assertEquals(first.gradeId(),next.gradeId());assertEquals(2,next.submissionVersion());assertEquals(2,next.version());assertEquals(1,history(2,5).items().getFirst().snapshot().submissionVersion());assertEquals(second,f.store.get(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false));}
 @Test void reviewUsesSubmittedInstructionVersionAfterAssignmentEdits(){f.parent.store.metadata(f.group,f.space,f.study,f.assignment,f.f.owner,2,"Changed instructions","New description",f.f.trace);var v=change(0,1,"Grade on original instructions");assertEquals(2,v.assignmentVersion());status(409,()->store.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,1,new SubmissionGradeInput(80,"Wrong instructions",1,3),f.f.trace));assertEquals(3,f.parent.store.get(f.group,f.space,f.study,f.assignment).version());}
 @Test void closedAssignmentsAcceptGradeButArchivedParentsAreReadOnly(){f.parent.store.state(f.group,f.space,f.study,f.assignment,f.f.owner,2,"CLOSED",f.f.trace);assertTrue(get(f.f.owner,true).canWrite());var v=change(0,1,"Review after close");f.parent.store.state(f.group,f.space,f.study,f.assignment,f.f.owner,3,"RETIRED",f.f.trace);assertFalse(get(f.f.owner,true).canWrite());assertEquals(v,get(f.author,false).grade());status(409,()->change(1,1,"Review after close"));assertEquals(1,history(Long.MAX_VALUE,5).items().size());}
 @Test void retiredStudyFreezesGradeWithoutHidingPriorAudit(){var v=change(0,1,"Before archive");f.parent.parent.store.state(f.group,f.space,f.study,f.f.owner,1,"RETIRED",f.f.trace);assertFalse(get(f.f.owner,true).canWrite());status(409,()->change(1,1,"After archive"));assertEquals(v,history(Long.MAX_VALUE,5).items().getFirst().snapshot());}
 @Test void peerAndWrongParentReferencesCannotReadCurrentOrHistory(){change(0,1,"Private grade");var peer=f.f.ids.next();status(404,()->get(peer,false));status(404,()->store.history(f.group,f.space,f.study,f.assignment,answer.submissionId(),peer,false,Long.MAX_VALUE,5));status(404,()->store.get(f.f.ids.next(),f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,true));status(404,()->store.get(f.group,f.f.ids.next(),f.study,f.assignment,answer.submissionId(),f.f.owner,true));status(404,()->store.get(f.group,f.space,f.study,f.f.ids.next(),answer.submissionId(),f.f.owner,true));status(404,()->store.get(f.group,f.space,f.study,f.assignment,f.f.ids.next(),f.f.owner,true));}
 @Test void historyUsesIndependentDescendingGradeCursor(){for(int n=0;n<7;n++)change(n,1,"Comment "+n);var first=history(Long.MAX_VALUE,5);assertEquals(List.of(7L,6L,5L,4L,3L),first.items().stream().map(SubmissionGradeStore.Revision::version).toList());assertEquals(3L,first.nextBefore());var second=history(first.nextBefore(),5);assertEquals(List.of(2L,1L),second.items().stream().map(SubmissionGradeStore.Revision::version).toList());assertNull(second.nextBefore());}
 @Test void concurrentInitialAndExistingCommentsHaveExactlyOneWinner()throws Exception{
  try(var executor=Executors.newVirtualThreadPerTaskExecutor()){for(int round=0;round<2;round++){long expected=round;var tasks=new ArrayList<Future<Boolean>>();var barrier=new CyclicBarrier(2);for(int n=0;n<2;n++){String text="Round "+round+" / "+n;tasks.add(executor.submit(()->{barrier.await();try{change(expected,1,text);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));}assertNotEquals(tasks.get(0).get(20,TimeUnit.SECONDS),tasks.get(1).get(20,TimeUnit.SECONDS));assertEquals(round+1,get(f.author,false).grade().version());}}
 }
 @Test void simultaneousResubmissionNeverAttachesOldReviewToNewAnswer()throws Exception{
  try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var submission=executor.submit(()->{barrier.await();return f.submit(f.f.key(),1,2,"Concurrent answer").submission();});var grade=executor.submit(()->{barrier.await();try{return change(0,1,"Reviewed original");}catch(ResponseStatusException e){assertEquals(409,e.getStatusCode().value());return null;}});assertEquals(2,submission.get(20,TimeUnit.SECONDS).version());var reviewed=grade.get(20,TimeUnit.SECONDS);if(reviewed!=null)assertEquals(1,reviewed.submissionVersion());assertEquals(reviewed,get(f.author,false).grade());}
 }
 @Test void outboxFailureRollsBackInitialAndCorrectedGradeAudit(){String constraint="grade_fail_"+answer.submissionId().toString().replace("-","");String check=" CHECK(aggregatetype<>'submission-grade' OR trace_id<>'"+f.f.trace+"') NOT VALID";f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+constraint+check);try{assertThrows(RuntimeException.class,()->change(0,1,"Fail initial"));assertNull(get(f.author,false).grade());assertTrue(history(Long.MAX_VALUE,5).items().isEmpty());}finally{f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+constraint);}var saved=change(0,1,"Saved");f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+constraint+check);try{assertThrows(RuntimeException.class,()->change(1,1,"Fail correction"));assertEquals(saved,get(f.author,false).grade());assertEquals(1,history(Long.MAX_VALUE,5).items().size());assertEquals(1,f.events(saved.gradeId()));}finally{f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+constraint);}}
 @Test void databaseRejectsMissingReviewedRevisionAndDuplicateGrade(){var v=change(0,1,"Validated provenance");assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.jdbc.update("UPDATE submission_grade SET submission_version=999999 WHERE grade_id=?",v.gradeId()));assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.jdbc.update("INSERT INTO submission_grade SELECT ?,submission_id,assignment_id,study_id,group_id,space_id,author_id,version,submission_version,grader_id,score,snapshot FROM submission_grade WHERE grade_id=?",f.f.ids.next(),v.gradeId()));assertEquals(v,get(f.author,false).grade());}

 @Test void zeroAndHundredAreGradesAndChangingOnlyScoreCreatesRevision(){var a=store.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,0,new SubmissionGradeInput(0,"Same reason",1,2),f.f.trace);assertEquals(0,a.score());var b=store.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,1,new SubmissionGradeInput(100,"Same reason",1,2),f.f.trace);assertEquals(a.gradeId(),b.gradeId());assertEquals(2,b.version());assertEquals(100,b.score());assertEquals(0,history(2,5).items().getFirst().snapshot().score());for(int score:List.of(-1,101,Integer.MAX_VALUE))status(400,()->store.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,2,new SubmissionGradeInput(score,"Invalid",1,2),f.f.trace));assertEquals(2,f.events(b.gradeId()));}
 @Test void currentOwnerCannotGradeOwnSubmissionEvenForNoOpOrAfterClose(){var own=f.store.submit(f.group,f.space,f.study,f.assignment,f.f.owner,0,2,f.f.key(),"Owner answer",f.f.trace).submission();assertFalse(store.get(f.group,f.space,f.study,f.assignment,own.submissionId(),f.f.owner,true).canWrite());status(403,()->store.change(f.group,f.space,f.study,f.assignment,own.submissionId(),f.f.owner,0,new SubmissionGradeInput(100,"Self grade",1,2),f.f.trace));f.parent.store.state(f.group,f.space,f.study,f.assignment,f.f.owner,2,"CLOSED",f.f.trace);status(403,()->store.change(f.group,f.space,f.study,f.assignment,own.submissionId(),f.f.owner,0,new SubmissionGradeInput(0,"Self after close",1,2),f.f.trace));assertNull(store.get(f.group,f.space,f.study,f.assignment,own.submissionId(),f.f.owner,true).grade());assertEquals(0,f.f.jdbc.queryForObject("SELECT count(*) FROM submission_grade WHERE submission_id=?",Integer.class,own.submissionId()));}
 @Test void gradeDoesNotMutateFeedbackRequestParentsOrPrivateProgress(){var feedback=new SubmissionFeedbackStore(f.f.source,f.parent.store,f.store,Clock.systemUTC());var opinion=feedback.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,0,new SubmissionFeedbackInput("Independent",1,2),f.f.trace);var requests=new ResubmissionRequestStore(f.f.source,f.parent.store,Clock.systemUTC());var request=requests.change(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.f.owner,0,new ResubmissionRequestInput("REQUEST","Revise",1,2),f.f.trace);var task=f.parent.store.get(f.group,f.space,f.study,f.assignment);var v=change(0,1,"A score, not automatic completion");assertEquals(opinion,feedback.get(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false).feedback());assertEquals(request,requests.get(f.group,f.space,f.study,f.assignment,answer.submissionId(),f.author,false).request());assertEquals(task,f.parent.store.get(f.group,f.space,f.study,f.assignment));assertEquals(answer,f.store.mine(f.group,f.space,f.study,f.assignment,f.author,true).submission());assertEquals(1,f.events(v.gradeId()));}
 @Test void databaseRejectsSelfGraderAndOutOfRangeScore(){var v=change(0,1,"Reason");assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.jdbc.update("UPDATE submission_grade SET grader_id=author_id WHERE grade_id=?",v.gradeId()));assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.jdbc.update("UPDATE submission_grade SET score=101 WHERE grade_id=?",v.gradeId()));assertEquals(v,get(f.author,false).grade());}
}
